-- Daily challenges for 2026-10-09: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-09

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('taking-real-breaks-at-work', 'Taking Real Breaks at Work', 'For anyone who eats lunch at the desk, skips breaks, and reaches the end of the workday drained. Each day is one small way to step away, reset your body and mind, and come back clearer, whatever kind of work you do.', 'Work', 365, array['Work', 'Burnout', 'Stress']::text[], 1, '2026-10-09T17:00:00+00:00'::timestamptz),
  ('speaking-up-in-groups', 'Speaking Up in Groups', 'For anyone who has something to say in a meeting, class or group conversation and stays quiet. Each day is one small, low-stakes step toward sharing a thought, asking a question, or disagreeing kindly, so your voice gets heard.', 'Confidence', 365, array['Assertiveness', 'Social Anxiety', 'Communication']::text[], 1, '2026-10-09T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('taking-real-breaks-at-work', 'speaking-up-in-groups');

